<?php require '../config/database.php';require '../config/auth.php';require_role('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO marks(student_id,semester,subject,marks) VALUES(?,?,?,?)');$q->execute([(int)$_POST['student_id'],(int)$_POST['semester'],trim($_POST['subject']),(int)$_POST['marks']]);$msg='Marks added.';}$students=$pdo->query('SELECT id,student_code,name FROM students ORDER BY name')->fetchAll();$page_title='Manage Marks';require '../includes/header.php';?><h1>Manage Marks</h1><p class="muted">Add marks. The PPT specifies six semesters and four subjects per semester.</p><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="card"><form method="post"><div class="form"><label>Student</label><select name="student_id"><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=$s['student_code']?> - <?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="form"><label>Semester</label><select name="semester"><?php for($i=1;$i<=6;$i++):?><option><?=$i?></option><?php endfor;?></select></div><div class="form"><label>Subject</label><input name="subject" required></div><div class="form"><label>Marks</label><input type="number" name="marks" min="0" max="100" required></div><button class="btn">Add Marks</button></form></div><?php require '../includes/footer.php';?>
